AssistantMessageToolRequest(name='create', tool_call_id='tooluse_hhvJszR8g3UYCiwpHlYmXh', arguments={'file_text': '/* ===== RESET & BASE ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-base:       #0d0d0d;
  --bg-surface:    #161616;
  --bg-raised:     #1f1f1f;
  --bg-hover:      #2a2a2a;
  --border:        #2e2e2e;
  --accent:        #e8c46a;
  --accent-dark:   #c9a84c;
  --accent-dim:    rgba(232,196,106,.12);
  --red:           #e05252;
  --text-primary:  #f0f0f0;
  --text-secondary:#a0a0a0;
  --text-muted:    #606060;
  --radius-sm:     6px;
  --radius-md:     12px;
  --radius-lg:     20px;
  --shadow-card:   0 4px 24px rgba(0,0,0,.5);
  --transition:    0.22s cubic-bezier(.4,0,.2,1);
  --max-w:         1280px;
}

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', system-ui, sans-serif;
  background: var(--bg-base);
  color: var(--text-primary);
  line-height: 1.6;
  min-height: 100vh;
}

img { display: block; max-width: 100%; }
a  { color: inherit; text-decoration: none; }
button { cursor: pointer; border: none; background: none; font: inherit; }
ul { list-style: none; }

/* ===== SKIP LINK ===== */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  background: var(--accent);
  color: #000;
  padding: .5rem 1rem;
  border-radius: 0 0 var(--radius-sm) var(--radius-sm);
  font-weight: 700;
  z-index: 9999;
  transition: top var(--transition);
}
.skip-link:focus { top: 0; }

/* ===== UTILITY ===== */
.container { max-width: var(--max-w); margin: 0 auto; padding: 0 1.5rem; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
.badge { display: inline-block; font-size: .7rem; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; padding: .25rem .6rem; border-radius: 100px; }
.badge--sale    { background: var(--red);    color: #fff; }
.badge--new     { background: var(--accent); color: #000; }
.badge--limited { background: #5b4fcf;       color: #fff; }
.tag { display: inline-block; font-size: .75rem; color: var(--text-secondary); background: var(--bg-raised); border: 1px solid var(--border); border-radius: 100px; padding: .2rem .7rem; }

/* ===== HEADER ===== */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(13,13,13,.88);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--border);
}
.header-inner {
  display: flex;
  align-items: center;
  gap: 2rem;
  height: 64px;
}
.logo {
  font-size: 1.35rem;
  font-weight: 800;
  letter-spacing: -.03em;
  color: var(--text-primary);
  white-space: nowrap;
}
.logo span { color: var(--accent); }

.main-nav { flex: 1; }
.main-nav ul {
  display: flex;
  gap: .25rem;
}
.main-nav a {
  font-size: .875rem;
  font-weight: 500;
  color: var(--text-secondary);
  padding: .4rem .75rem;
  border-radius: var(--radius-sm);
  transition: color var(--transition), background var(--transition);
}
.main-nav a:hover,
.main-nav a[aria-current="page"] { color: var(--text-primary); background: var(--bg-raised); }

.header-actions { display: flex; align-items: center; gap: .5rem; margin-left: auto; }
.header-actions .icon-btn {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px; height: 40px;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  transition: color var(--transition), background var(--transition);
}
.header-actions .icon-btn:hover { color: var(--text-primary); background: var(--bg-raised); }
.cart-count {
  position: absolute;
  top: 4px; right: 4px;
  width: 16px; height: 16px;
  background: var(--accent);
  color: #000;
  font-size: .6rem;
  font-weight: 800;
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  line-height: 1;
}
.search-form { display: flex; align-items: center; gap: .5rem; }
.search-input {
  background: var(--bg-raised);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-size: .875rem;
  padding: .4rem .75rem;
  width: 200px;
  transition: border-color var(--transition), width var(--transition);
}
.search-input::placeholder { color: var(--text-muted); }
.search-input:focus { outline: 2px solid var(--accent); outline-offset: 2px; border-color: var(--accent); width: 260px; }
.nav-toggle { display: none; }

/* ===== ANNOUNCEMENT BAR ===== */
.announce-bar {
  background: var(--accent);
  color: #000;
  text-align: center;
  font-size: .8rem;
  font-weight: 700;
  letter-spacing: .05em;
  padding: .55rem 1.5rem;
}
.announce-bar a { color: #000; text-decoration: underline; }

/* ===== HERO ===== */
.hero {
  position: relative;
  min-height: 580px;
  display: flex;
  align-items: center;
  overflow: hidden;
  background: var(--bg-surface);
}
.hero-bg {
  position: absolute; inset: 0;
  background:
    radial-gradient(ellipse 70% 60% at 70% 50%, rgba(232,196,106,.08) 0%, transparent 70%),
    radial-gradient(ellipse 40% 80% at 10% 50%, rgba(91,79,207,.1) 0%, transparent 60%),
    linear-gradient(135deg, #0d0d0d 0%, #161616 100%);
}
.hero-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
  position: relative;
  z-index: 1;
  padding: 5rem 0;
}
.hero-eyebrow {
  font-size: .75rem;
  font-weight: 700;
  letter-spacing: .15em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 1rem;
}
.hero-title {
  font-size: clamp(2.2rem, 5vw, 3.8rem);
  font-weight: 900;
  line-height: 1.08;
  letter-spacing: -.04em;
  margin-bottom: 1.25rem;
}
.hero-title em { font-style: normal; color: var(--accent); }
.hero-desc {
  font-size: 1.05rem;
  color: var(--text-secondary);
  max-width: 42ch;
  margin-bottom: 2rem;
  line-height: 1.7;
}
.hero-actions { display: flex; gap: 1rem; flex-wrap: wrap; }
.btn {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  font-size: .9rem;
  font-weight: 700;
  padding: .75rem 1.5rem;
  border-radius: var(--radius-md);
  transition: background var(--transition), color var(--transition), transform var(--transition), box-shadow var(--transition);
}
.btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }
.btn--primary {
  background: var(--accent);
  color: #000;
}
.btn--primary:hover { background: var(--accent-dark); transform: translateY(-1px); box-shadow: 0 6px 20px rgba(232,196,106,.3); }
.btn--ghost {
  background: transparent;
  color: var(--text-primary);
  border: 1.5px solid var(--border);
}
.btn--ghost:hover { border-color: var(--text-secondary); background: var(--bg-raised); }
.hero-stats {
  display: flex;
  gap: 2rem;
  margin-top: 2.5rem;
  padding-top: 2rem;
  border-top: 1px solid var(--border);
}
.hero-stat-num { font-size: 1.5rem; font-weight: 800; color: var(--text-primary); letter-spacing: -.02em; }
.hero-stat-label { font-size: .75rem; color: var(--text-muted); margin-top: .1rem; }

.hero-visual {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
}
.hero-product-card {
  background: var(--bg-raised);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 2rem;
  width: 100%;
  max-width: 360px;
  box-shadow: var(--shadow-card);
  position: relative;
  overflow: hidden;
}
.hero-product-card::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 80% 60% at 50% 0%, rgba(232,196,106,.06) 0%, transparent 70%);
  pointer-events: none;
}
.hero-product-img {
  width: 100%;
  aspect-ratio: 1;
  border-radius: var(--radius-md);
  background: linear-gradient(135deg, #2a2a2a 0%, #1a1a1a 100%);
  display: flex; align-items: center; justify-content: center;
  font-size: 5rem;
  margin-bottom: 1.25rem;
}
.hero-product-meta { display: flex; justify-content: space-between; align-items: flex-start; gap: 1rem; }
.hero-product-name { font-size: 1.1rem; font-weight: 700; margin-bottom: .25rem; }
.hero-product-sub  { font-size: .8rem; color: var(--text-muted); }
.hero-product-price { font-size: 1.3rem; font-weight: 800; color: var(--accent); white-space: nowrap; }
.hero-product-old  { font-size: .8rem; color: var(--text-muted); text-decoration: line-through; }
.hero-badge-stack  { position: absolute; top: 1rem; right: 1rem; display: flex; flex-direction: column; gap: .35rem; align-items: flex-end; }

/* ===== SECTION HEADERS ===== */
.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 2rem;
  flex-wrap: wrap;
}
.section-eyebrow {
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .15em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: .35rem;
}
.section-title {
  font-size: clamp(1.4rem, 3vw, 2rem);
  font-weight: 800;
  letter-spacing: -.03em;
  line-height: 1.2;
}
.section-desc { font-size: .9rem; color: var(--text-secondary); margin-top: .4rem; max-width: 55ch; }
.view-all {
  font-size: .85rem;
  font-weight: 600;
  color: var(--accent);
  display: flex; align-items: center; gap: .3rem;
  white-space: nowrap;
  transition: gap var(--transition);
}
.view-all:hover { gap: .55rem; }
.view-all:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; border-radius: var(--radius-sm); }

/* ===== CATEGORIES ===== */
.categories { padding: 4rem 0 2rem; }
.categories-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
  gap: 1rem;
}
.category-card {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 1.5rem 1rem;
  text-align: center;
  transition: border-color var(--transition), background var(--transition), transform var(--transition);
  cursor: pointer;
}
.category-card:hover { border-color: var(--accent); background: var(--bg-raised); transform: translateY(-3px); }
.category-card:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }
.category-icon { font-size: 2rem; margin-bottom: .75rem; }
.category-name { font-size: .85rem; font-weight: 600; color: var(--text-secondary); }
.category-count { font-size: .72rem; color: var(--text-muted); margin-top: .2rem; }

/* ===== PRODUCT CARDS ===== */
.product-card {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: border-color var(--transition), transform var(--transition), box-shadow var(--transition);
  position: relative;
  display: flex;
  flex-direction: column;
}
.product-card:hover { border-color: var(--border); transform: translateY(-4px); box-shadow: var(--shadow-card); }
.product-card-img {
  aspect-ratio: 1;
  background: var(--bg-raised);
  display: flex; align-items: center; justify-content: center;
  font-size: 3.5rem;
  position: relative;
  overflow: hidden;
}
.product-card-img .overlay-actions {
  position: absolute;
  bottom: 0; left: 0; right: 0;
  display: flex;
  gap: .5rem;
  padding: .75rem;
  background: linear-gradient(0deg, rgba(0,0,0,.8) 0%, transparent 100%);
  transform: translateY(110%);
  transition: transform var(--transition);
}
.product-card:hover .overlay-actions,
.product-card:focus-within .overlay-actions { transform: translateY(0); }
.overlay-btn {
  flex: 1;
  background: var(--bg-raised);
  border: 1px solid var(--border);
  color: var(--text-primary);
  font-size: .8rem;
  font-weight: 600;
  padding: .5rem;
  border-radius: var(--radius-sm);
  text-align: center;
  transition: background var(--transition), border-color var(--transition);
}
.overlay-btn:hover { background: var(--accent); border-color: var(--accent); color: #000; }
.overlay-btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.product-card-body { padding: 1rem; flex: 1; display: flex; flex-direction: column; }
.product-card-badges { display: flex; gap: .4rem; margin-bottom: .6rem; flex-wrap: wrap; }
.product-card-name { font-size: .95rem; font-weight: 700; line-height: 1.3; margin-bottom: .25rem; }
.product-card-brand { font-size: .75rem; color: var(--text-muted); margin-bottom: .5rem; }
.product-card-rating {
  display: flex; align-items: center; gap: .35rem;
  font-size: .78rem; color: var(--text-secondary); margin-bottom: .75rem;
}
.stars { color: var(--accent); letter-spacing: -.05em; }
.product-card-footer { display: flex; align-items: center; justify-content: space-between; margin-top: auto; }
.price-group { display: flex; align-items: baseline; gap: .4rem; }
.price-current { font-size: 1.1rem; font-weight: 800; color: var(--text-primary); }
.price-original { font-size: .8rem; color: var(--text-muted); text-decoration: line-through; }
.price-pct { font-size: .75rem; font-weight: 700; color: var(--red); }
.add-to-cart-btn {
  width: 36px; height: 36px;
  border-radius: var(--radius-sm);
  background: var(--accent);
  color: #000;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.2rem;
  font-weight: 700;
  transition: background var(--transition), transform var(--transition);
  flex-shrink: 0;
}
.add-to-cart-btn:hover { background: var(--accent-dark); transform: scale(1.1); }
.add-to-cart-btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }
.wishlist-btn {
  position: absolute;
  top: .75rem; right: .75rem;
  width: 32px; height: 32px;
  background: rgba(0,0,0,.55);
  backdrop-filter: blur(4px);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  display: flex; align-items: center; justify-content: center;
  font-size: .9rem;
  transition: background var(--transition), color var(--transition);
}
.wishlist-btn:hover,
.wishlist-btn[aria-pressed="true"] { background: rgba(224,82,82,.2); color: var(--red); border-color: var(--red); }
.wishlist-btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }

/* ===== FEATURED PRODUCTS ===== */
.featured-products { padding: 4rem 0; }
.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 1.25rem;
}

/* ===== DEALS ===== */
.deals-section { padding: 4rem 0; background: var(--bg-surface); }
.deals-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.5rem;
}
.deal-banner {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  min-height: 240px;
  display: flex;
  align-items: flex-end;
  padding: 2rem;
  background: var(--bg-raised);
  border: 1px solid var(--border);
  transition: transform var(--transition), box-shadow var(--transition);
}
.deal-banner:hover { transform: translateY(-3px); box-shadow: var(--shadow-card); }
.deal-banner:focus-visible { outline: 2px solid var(--accent); outline-offset: 4px; }
.deal-banner--wide { grid-column: 1 / -1; min-height: 180px; align-items: center; }
.deal-bg {
  position: absolute; inset: 0;
  pointer-events: none;
}
.deal-content { position: relative; z-index: 1; }
.deal-label { font-size: .7rem; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--accent); margin-bottom: .35rem; }
.deal-title { font-size: 1.4rem; font-weight: 800; letter-spacing: -.02em; line-height: 1.2; margin-bottom: .5rem; }
.deal-sub   { font-size: .85rem; color: var(--text-secondary); margin-bottom: 1rem; }
.countdown  { display: flex; gap: .75rem; margin-bottom: 1.25rem; }
.countdown-unit { text-align: center; }
.countdown-num { font-size: 1.5rem; font-weight: 800; color: var(--accent); line-height: 1; }
.countdown-sep { font-size: 1.5rem; font-weight: 800; color: var(--text-muted); line-height: 1; align-self: flex-start; }
.countdown-label { font-size: .6rem; color: var(--text-muted); letter-spacing: .08em; text-transform: uppercase; margin-top: .2rem; }

/* ===== MARQUEE ===== */
.marquee-strip {
  background: var(--accent);
  color: #000;
  padding: .7rem 0;
  overflow: hidden;
  font-size: .78rem;
  font-weight: 800;
  letter-spacing: .06em;
  text-transform: uppercase;
}
.marquee-track {
  display: flex;
  gap: 3rem;
  width: max-content;
  animation: marquee 28s linear infinite;
}
.marquee-track:hover { animation-play-state: paused; }
.marquee-item { white-space: nowrap; }
.marquee-dot { margin: 0 1rem; opacity: .5; }
@keyframes marquee { from { transform: translateX(0); } to { transform: translateX(-50%); } }

/* ===== EDITORIAL ===== */
.editorial { padding: 4rem 0; }
.editorial-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 1.5rem;
}
.editorial-card {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform var(--transition), border-color var(--transition), box-shadow var(--transition);
}
.editorial-card:hover { transform: translateY(-4px); border-color: var(--border); box-shadow: var(--shadow-card); }
.editorial-card:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }
.editorial-card--featured { grid-column: 1 / -1; flex-direction: row; }
.editorial-img {
  aspect-ratio: 16/9;
  background: var(--bg-raised);
  display: flex; align-items: center; justify-content: center;
  font-size: 4rem;
  flex-shrink: 0;
  position: relative;
  overflow: hidden;
}
.editorial-card--featured .editorial-img { flex: 0 0 45%; aspect-ratio: auto; font-size: 6rem; }
.editorial-img-gradient {
  position: absolute; inset: 0;
  pointer-events: none;
}
.editorial-body { padding: 1.5rem; flex: 1; display: flex; flex-direction: column; }
.editorial-meta { display: flex; align-items: center; gap: .5rem; margin-bottom: .75rem; flex-wrap: wrap; }
.editorial-author { font-size: .75rem; color: var(--text-muted); }
.editorial-date   { font-size: .75rem; color: var(--text-muted); }
.editorial-title  { font-size: 1.1rem; font-weight: 700; line-height: 1.35; margin-bottom: .5rem; }
.editorial-card--featured .editorial-title { font-size: 1.5rem; }
.editorial-excerpt { font-size: .85rem; color: var(--text-secondary); line-height: 1.65; flex: 1; }
.editorial-read-more {
  display: inline-flex; align-items: center; gap: .35rem;
  font-size: .82rem; font-weight: 600; color: var(--accent);
  margin-top: 1rem;
  transition: gap var(--transition);
}
.editorial-read-more:hover { gap: .55rem; }

/* ===== BRANDS ===== */
.brands-section { padding: 3rem 0; border-top: 1px solid var(--border); border-bottom: 1px solid var(--border); background: var(--bg-surface); }
.brands-label { text-align: center; font-size: .72rem; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--text-muted); margin-bottom: 1.75rem; }
.brands-list { display: flex; align-items: center; justify-content: center; gap: 3rem; flex-wrap: wrap; }
.brand-item {
  font-size: 1.2rem;
  font-weight: 800;
  letter-spacing: -.03em;
  color: var(--text-muted);
  transition: color var(--transition);
}
.brand-item:hover { color: var(--text-secondary); }

/* ===== NEWSLETTER ===== */
.newsletter { padding: 5rem 0; }
.newsletter-inner {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 3rem;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 3rem;
  align-items: center;
  position: relative;
  overflow: hidden;
}
.newsletter-inner::before {
  content: '';
  position: absolute; inset: 0;
  background: radial-gradient(ellipse 60% 80% at 100% 50%, rgba(232,196,106,.05) 0%, transparent 60%);
  pointer-events: none;
}
.newsletter-title { font-size: 1.6rem; font-weight: 800; letter-spacing: -.03em; margin-bottom: .5rem; }
.newsletter-sub   { font-size: .9rem; color: var(--text-secondary); }
.newsletter-form  { display: flex; gap: .75rem; flex-wrap: wrap; position: relative; z-index: 1; }
.newsletter-input {
  background: var(--bg-raised);
  border: 1.5px solid var(--border);
  border-radius: var(--radius-md);
  color: var(--text-primary);
  font-size: .9rem;
  padding: .75rem 1.2rem;
  min-width: 260px;
  transition: border-color var(--transition);
}
.newsletter-input::placeholder { color: var(--text-muted); }
.newsletter-input:focus { outline: 2px solid var(--accent); outline-offset: 2px; border-color: var(--accent); }

/* ===== FOOTER ===== */
.site-footer {
  background: var(--bg-surface);
  border-top: 1px solid var(--border);
  padding: 4rem 0 2rem;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 3rem;
  margin-bottom: 3rem;
}
.footer-brand p { font-size: .875rem; color: var(--text-secondary); margin-top: .75rem; max-width: 30ch; line-height: 1.7; }
.footer-socials { display: flex; gap: .5rem; margin-top: 1.25rem; }
.social-btn {
  width: 36px; height: 36px;
  background: var(--bg-raised);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  display: flex; align-items: center; justify-content: center;
  font-size: .9rem;
  transition: color var(--transition), border-color var(--transition), background var(--transition);
}
.social-btn:hover { color: var(--accent); border-color: var(--accent); background: var(--accent-dim); }
.social-btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }
.footer-col-title { font-size: .78rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--text-secondary); margin-bottom: 1.1rem; }
.footer-links { display: flex; flex-direction: column; gap: .6rem; }
.footer-links a { font-size: .875rem; color: var(--text-muted); transition: color var(--transition); }
.footer-links a:hover { color: var(--text-primary); }
.footer-links a:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; border-radius: 2px; }
.footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
}
.footer-copy { font-size: .8rem; color: var(--text-muted); }
.footer-legal { display: flex; gap: 1.5rem; flex-wrap: wrap; }
.footer-legal a { font-size: .8rem; color: var(--text-muted); transition: color var(--transition); }
.footer-legal a:hover { color: var(--text-secondary); }

/* ===== TOAST ===== */
.toast-container {
  position: fixed;
  bottom: 1.5rem; right: 1.5rem;
  display: flex; flex-direction: column; gap: .5rem;
  z-index: 9999;
  pointer-events: none;
}
.toast {
  background: var(--bg-raised);
  border: 1px solid var(--border);
  border-left: 3px solid var(--accent);
  border-radius: var(--radius-md);
  padding: .85rem 1.25rem;
  font-size: .875rem;
  font-weight: 500;
  color: var(--text-primary);
  box-shadow: 0 8px 32px rgba(0,0,0,.6);
  display: flex; align-items: center; gap: .6rem;
  animation: toast-in .3s cubic-bezier(.34,1.56,.64,1) both;
  pointer-events: all;
  max-width: 320px;
}
.toast.removing { animation: toast-out .2s ease-in both; }
@keyframes toast-in  { from { opacity: 0; transform: translateX(20px) scale(.9); } to { opacity: 1; transform: none; } }
@keyframes toast-out { to   { opacity: 0; transform: translateX(20px) scale(.9); } }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .editorial-card--featured { grid-column: auto; flex-direction: column; }
  .editorial-card--featured .editorial-img { flex: none; aspect-ratio: 16/9; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .newsletter-inner { grid-template-columns: 1fr; }
  .newsletter-form { justify-content: flex-start; }
}

@media (max-width: 768px) {
  .hero-grid { grid-template-columns: 1fr; gap: 2.5rem; padding: 3.5rem 0; }
  .hero-visual { display: none; }
  .deals-grid { grid-template-columns: 1fr; }
  .deal-banner--wide { grid-column: auto; }
  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-card--featured { flex-direction: column; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .main-nav { display: none; }
  .search-form { display: none; }
  .nav-toggle { display: flex; align-items: center; justify-content: center; width: 40px; height: 40px; border-radius: var(--radius-sm); color: var(--text-secondary); transition: color var(--transition); }
  .nav-toggle:hover { color: var(--text-primary); background: var(--bg-raised); }
  .nav-toggle:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }
}

@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
  .hero-stats { flex-direction: column; gap: 1rem; }
  .newsletter-input { min-width: unset; width: 100%; }
  .newsletter-form { flex-direction: column; }
  .categories-grid { grid-template-columns: repeat(3, 1fr); }
  .products-grid { grid-template-columns: repeat(2, 1fr); }
  .brands-list { gap: 1.5rem; }
}
