  margin-bottom: .35rem;
}
.section-title {
  font-size: clamp(1.4rem, 3vw, 2rem);
  font-weight: 800;
  letter-spacing: -.03em;
  line-height: 1.2;
}
.section-desc { font-size: .9rem; color: var(--text-secondary); margin-top: .4rem; max-width: 55ch; }
.view-all {
  font-size: .85rem;
  font-weight: 600;
  color: var(--accent);
