.social-btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }
.footer-col-title { font-size: .78rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--text-secondary); margin-bottom: 1.1rem; }
.footer-links { display: flex; flex-direction: column; gap: .6rem; }
.footer-links a { font-size: .875rem; color: var(--text-muted); transition: color var(--transition); }
